#[inline]
fn destack_audio_device_open_replay(
    binding: &BindingCallContext,
    world: RuntimeWorld,
    out: *mut resource::AudioDeviceHandle,
    id: NativeStringRef,
    options: AudioDeviceOpenOptions,
) -> RuntimeResult<()> {
    let _ = (&id, &options);

    binding.trace().run_binding_without_context(
        AUDIO_DEVICE_OPEN,
        binding.replay_payload_for(AUDIO_DEVICE_OPEN)?,
        || match world {
            RuntimeWorld::Host => unsafe {
                platform_native::destack_audio_device_open(binding, out, id, options)
            },
            RuntimeWorld::Simulation => unsafe {
                platform_simulation_native::destack_audio_device_open(binding, out, id, options)
            },
        },
        |result| {
            if let Ok(()) = result {
                let result_value: resource::AudioDeviceHandle = unsafe { out.read() };
                let result_recorded = result_value;
                let payload = AudioDeviceOpenReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AudioDeviceOpenReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    unsafe { out.write(value) };
                    Ok(())
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    )
}

