/// VM replay implementations for audio bindings.
#[inline]
fn destack_audio_backend_list_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        AUDIO_BACKEND_LIST,
        binding.replay_payload_for(AUDIO_BACKEND_LIST)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_audio_backend_list(binding, context),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_audio_backend_list(binding, context)
            }
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: VmSlice<AudioBackendDescriptorVm> = value.clone();
                let result_recorded_raw = result_value.values(context)?;
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item =
                        <AudioBackendDescriptorVm as VmAggregateCodec>::decode_with_context(
                            context,
                            result_recorded_item_value,
                        )?;
                    let result_recorded_item_recorded_backend = result_recorded_item.backend;
                    let result_recorded_item_recorded_name = {
                        let result_recorded_item_recorded_name_ref = context
                            .string_ref(result_recorded_item.name)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        result_recorded_item_recorded_name_ref.as_str().to_string()
                    };
                    let result_recorded_item_recorded_support = result_recorded_item.support;
                    let result_recorded_item_recorded_priority = result_recorded_item.priority;
                    let result_recorded_item_recorded_capability_flags =
                        result_recorded_item.capability_flags;
                    let result_recorded_item_recorded_supported_device_list_flags =
                        result_recorded_item.supported_device_list_flags;
                    let result_recorded_item_recorded_supported_device_open_flags =
                        result_recorded_item.supported_device_open_flags;
                    let result_recorded_item_recorded_supported_stream_flags =
                        result_recorded_item.supported_stream_flags;
                    let result_recorded_item_recorded_supported_stream_requirement_flags =
                        result_recorded_item.supported_stream_requirement_flags;
                    let result_recorded_item_recorded_supported_event_subscription_flags =
                        result_recorded_item.supported_event_subscription_flags;
                    let result_recorded_item_recorded_supported_stream_clock_domains =
                        result_recorded_item.supported_stream_clock_domains;
                    let result_recorded_item_recorded = AudiobackenddescriptorReplayRecord {
                        backend: result_recorded_item_recorded_backend,
                        name: result_recorded_item_recorded_name,
                        support: result_recorded_item_recorded_support,
                        priority: result_recorded_item_recorded_priority,
                        capability_flags: result_recorded_item_recorded_capability_flags,
                        supported_device_list_flags:
                            result_recorded_item_recorded_supported_device_list_flags,
                        supported_device_open_flags:
                            result_recorded_item_recorded_supported_device_open_flags,
                        supported_stream_flags:
                            result_recorded_item_recorded_supported_stream_flags,
                        supported_stream_requirement_flags:
                            result_recorded_item_recorded_supported_stream_requirement_flags,
                        supported_event_subscription_flags:
                            result_recorded_item_recorded_supported_event_subscription_flags,
                        supported_stream_clock_domains:
                            result_recorded_item_recorded_supported_stream_clock_domains,
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = AudioBackendListReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AudioBackendListReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_builder =
                        VmSlice::<AudioBackendDescriptorVm>::builder(context, value.len())?;
                    for vm_result_item in value {
                        let vm_result_item_value_backend = vm_result_item.backend;
                        let vm_result_item_value_name = context
                            .string_handle(vm_result_item.name.as_str())
                            .map_err(Box::<RuntimeError>::from)?;
                        let vm_result_item_value_support = vm_result_item.support;
                        let vm_result_item_value_priority = vm_result_item.priority;
                        let vm_result_item_value_capability_flags = vm_result_item.capability_flags;
                        let vm_result_item_value_supported_device_list_flags =
                            vm_result_item.supported_device_list_flags;
                        let vm_result_item_value_supported_device_open_flags =
                            vm_result_item.supported_device_open_flags;
                        let vm_result_item_value_supported_stream_flags =
                            vm_result_item.supported_stream_flags;
                        let vm_result_item_value_supported_stream_requirement_flags =
                            vm_result_item.supported_stream_requirement_flags;
                        let vm_result_item_value_supported_event_subscription_flags =
                            vm_result_item.supported_event_subscription_flags;
                        let vm_result_item_value_supported_stream_clock_domains =
                            vm_result_item.supported_stream_clock_domains;
                        let vm_result_item_value = AudioBackendDescriptorVm {
                            backend: vm_result_item_value_backend,
                            name: vm_result_item_value_name,
                            support: vm_result_item_value_support,
                            priority: vm_result_item_value_priority,
                            capability_flags: vm_result_item_value_capability_flags,
                            supported_device_list_flags:
                                vm_result_item_value_supported_device_list_flags,
                            supported_device_open_flags:
                                vm_result_item_value_supported_device_open_flags,
                            supported_stream_flags: vm_result_item_value_supported_stream_flags,
                            supported_stream_requirement_flags:
                                vm_result_item_value_supported_stream_requirement_flags,
                            supported_event_subscription_flags:
                                vm_result_item_value_supported_event_subscription_flags,
                            supported_stream_clock_domains:
                                vm_result_item_value_supported_stream_clock_domains,
                        };
                        vm_result_builder.push(context, vm_result_item_value)?;
                    }
                    let vm_result = vm_result_builder.finish()?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_audio_backend_list_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_audio_clock_now_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    domain: AudioClockDomain,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        AUDIO_CLOCK_NOW,
        binding.replay_payload_for(AUDIO_CLOCK_NOW)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_audio_clock_now(binding, context, domain),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_audio_clock_now(binding, context, domain)
            }
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: u64 = value.clone();
                let result_recorded = result_value;
                let payload = AudioClockNowReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AudioClockNowReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_audio_clock_now_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_audio_clock_stream_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::AudioStreamHandle,
    domain: AudioStreamClockDomain,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        AUDIO_CLOCK_STREAM,
        binding.replay_payload_for(AUDIO_CLOCK_STREAM)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_audio_stream_clock(binding, context, handle, domain)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_audio_stream_clock(binding, context, handle, domain)
            }
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: AudioClockSnapshotVm = value.clone();
                let result_recorded_stream_frames = result_value.stream_frames;
                let result_recorded_clock_ns = result_value.clock_ns;
                let result_recorded_clock_quality = result_value.clock_quality;
                let result_recorded_callback_ns = if let Some(value) = result_value.callback_ns {
                    let result_recorded_callback_ns_inner = value;
                    Some(result_recorded_callback_ns_inner)
                } else {
                    None
                };
                let result_recorded_callback_quality = result_value.callback_quality;
                let result_recorded_input_adc_ns = if let Some(value) = result_value.input_adc_ns {
                    let result_recorded_input_adc_ns_inner = value;
                    Some(result_recorded_input_adc_ns_inner)
                } else {
                    None
                };
                let result_recorded_input_adc_quality = result_value.input_adc_quality;
                let result_recorded_output_dac_ns = if let Some(value) = result_value.output_dac_ns
                {
                    let result_recorded_output_dac_ns_inner = value;
                    Some(result_recorded_output_dac_ns_inner)
                } else {
                    None
                };
                let result_recorded_output_dac_quality = result_value.output_dac_quality;
                let result_recorded_device_ns = if let Some(value) = result_value.device_ns {
                    let result_recorded_device_ns_inner = value;
                    Some(result_recorded_device_ns_inner)
                } else {
                    None
                };
                let result_recorded_device_quality = result_value.device_quality;
                let result_recorded_monotonic_ns = result_value.monotonic_ns;
                let result_recorded = AudioClockSnapshot {
                    stream_frames: result_recorded_stream_frames,
                    clock_ns: result_recorded_clock_ns,
                    clock_quality: result_recorded_clock_quality,
                    callback_ns: result_recorded_callback_ns,
                    callback_quality: result_recorded_callback_quality,
                    input_adc_ns: result_recorded_input_adc_ns,
                    input_adc_quality: result_recorded_input_adc_quality,
                    output_dac_ns: result_recorded_output_dac_ns,
                    output_dac_quality: result_recorded_output_dac_quality,
                    device_ns: result_recorded_device_ns,
                    device_quality: result_recorded_device_quality,
                    monotonic_ns: result_recorded_monotonic_ns,
                };
                let payload = AudioClockStreamReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AudioClockStreamReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result_stream_frames = value.stream_frames;
                    let vm_result_clock_ns = value.clock_ns;
                    let vm_result_clock_quality = value.clock_quality;
                    let vm_result_callback_ns = if let Some(value) = value.callback_ns {
                        let vm_result_callback_ns_inner = value;
                        Some(vm_result_callback_ns_inner)
                    } else {
                        None
                    };
                    let vm_result_callback_quality = value.callback_quality;
                    let vm_result_input_adc_ns = if let Some(value) = value.input_adc_ns {
                        let vm_result_input_adc_ns_inner = value;
                        Some(vm_result_input_adc_ns_inner)
                    } else {
                        None
                    };
                    let vm_result_input_adc_quality = value.input_adc_quality;
                    let vm_result_output_dac_ns = if let Some(value) = value.output_dac_ns {
                        let vm_result_output_dac_ns_inner = value;
                        Some(vm_result_output_dac_ns_inner)
                    } else {
                        None
                    };
                    let vm_result_output_dac_quality = value.output_dac_quality;
                    let vm_result_device_ns = if let Some(value) = value.device_ns {
                        let vm_result_device_ns_inner = value;
                        Some(vm_result_device_ns_inner)
                    } else {
                        None
                    };
                    let vm_result_device_quality = value.device_quality;
                    let vm_result_monotonic_ns = value.monotonic_ns;
                    let vm_result = AudioClockSnapshot {
                        stream_frames: vm_result_stream_frames,
                        clock_ns: vm_result_clock_ns,
                        clock_quality: vm_result_clock_quality,
                        callback_ns: vm_result_callback_ns,
                        callback_quality: vm_result_callback_quality,
                        input_adc_ns: vm_result_input_adc_ns,
                        input_adc_quality: vm_result_input_adc_quality,
                        output_dac_ns: vm_result_output_dac_ns,
                        output_dac_quality: vm_result_output_dac_quality,
                        device_ns: vm_result_device_ns,
                        device_quality: vm_result_device_quality,
                        monotonic_ns: vm_result_monotonic_ns,
                    };
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_audio_clock_stream_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_audio_device_close_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    handle: resource::AudioDeviceHandle,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        AUDIO_DEVICE_CLOSE,
        binding.replay_payload_for(AUDIO_DEVICE_CLOSE)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_audio_device_close(binding, context, handle),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_audio_device_close(binding, context, handle)
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = AudioDeviceCloseReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AudioDeviceCloseReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_audio_device_close_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_audio_device_default_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    direction: AudioDeviceDirection,
    backend: AudioBackend,
    backendpolicy: AudioBackendSelectionPolicy,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        AUDIO_DEVICE_DEFAULT,
        binding.replay_payload_for(AUDIO_DEVICE_DEFAULT)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_audio_device_default(
                binding,
                context,
                direction,
                backend,
                backendpolicy,
            ),
            RuntimeWorld::Simulation => platform_simulation_vm::destack_audio_device_default(
                binding,
                context,
                direction,
                backend,
                backendpolicy,
            ),
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: vm::StringHandle = value.clone();
                let result_recorded = {
                    let result_recorded_ref = context
                        .string_ref(result_value)
                        .map_err(|error| RuntimeError::from(error).boxed())?;
                    result_recorded_ref.as_str().to_string()
                };
                let payload = AudioDeviceDefaultReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AudioDeviceDefaultReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = context
                        .string_handle(value.as_str())
                        .map_err(Box::<RuntimeError>::from)?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_audio_device_default_result(context, result)?;
    Ok(result)
}

