#[inline]
fn destack_audio_device_open_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::ExternalCallContext<'_>,
    world: RuntimeWorld,
    id: vm::StringHandle,
    options: AudioDeviceOpenOptionsVm,
) -> RuntimeResult<vm::Value> {
    let result = binding.trace().run_binding(
        AUDIO_DEVICE_OPEN,
        binding.replay_payload_for(AUDIO_DEVICE_OPEN)?,
        context,
        |context| match world {
            RuntimeWorld::Host => {
                platform_vm::destack_audio_device_open(binding, context, id, options)
            }
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_audio_device_open(binding, context, id, options)
            }
        },
        |_context, result| {
            if let Ok(value) = result {
                let result_value: resource::AudioDeviceHandle = value.clone();
                let result_recorded = result_value;
                let payload = AudioDeviceOpenReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    AudioDeviceOpenReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(value) => {
                    let vm_result = value;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_audio_device_open_result(context, result)?;
    Ok(result)
}

